    (143::BIGINT, 'Buen profe bastante comprensivo y manda trabajos de máximo 30 min'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-09-24T00:00:00+00:00'::TIMESTAMPTZ, '2bea78b70743ec29af76e919d3b4e4372e262bda04e869002cdb73a63194a0e5'::TEXT, ARRAY[681]::BIGINT[]),
    (143::BIGINT, 'Interesante y fácil, buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-09-17T00:00:00+00:00'::TIMESTAMPTZ, '51fc4fba1bbafeb9ef22a2836cf4b65abd419424558440938a0347dc0b74a383'::TEXT, ARRAY[681]::BIGINT[]),
    (143::BIGINT, 'La verdad, de lo mejor que existe como profesor, es bastante bueno, conciso con lo que hay que hacer y siempre que uno le escriba, lo ayuda para asegurarse que todos sus trabajos salgan con un 100. Ni idea como será ahora que el curso es presencial, pero de mi experiencia, lo volvería a llevar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'efb638a1a94168cfe591935cfee4204a7e247a8f3465c59dfe095fd3c37cd0e1'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Buen profe, siempre ayuda, revisa los trabajos antes de la entrega.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, '0e4d245572eba33ec254a2823a2e0ec5e8e4cc4c5940f14eadef064c6be6f97c'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a335377a68d7d22fb95558c608711f08518e6d2f030b0a41d42a4e850dbe8a3f'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El profe le da enfoque a la parte de gastronomia. Es super amable y muuuy comprensivo. En las 4 clases de la humanistica sí deja trabajos pero son mega faciles, se logran hacer en 1 hora. Un curso muy muy facil de aprobar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'e21cce7fc14d478862595b252a2b08d5a9922c2dafd3122f51eb8132bb6bb1a7'::TEXT, ARRAY[681]::BIGINT[]),
