    (143::BIGINT, 'Simplemente la Goat,'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2026-04-09T00:00:00+00:00'::TIMESTAMPTZ, '55ed0b2de8c6817f3c40ba61f3c0dc78bb2e0ba58f2b38583f6fe7f439fdbde0'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Chill. Muy bueno. Se pasa fácil.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-11T00:00:00+00:00'::TIMESTAMPTZ, '94192a704fad1b5b195195974d69802b985c87aff96419ffb561856c09168a18'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'El profe es excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-21T00:00:00+00:00'::TIMESTAMPTZ, '6bdedd6633acf41c99f29eaeb0cec8194387bbabe304e486a95da210fc43a1c5'::TEXT, ARRAY[681]::BIGINT[]),
    (143::BIGINT, 'Profe muy bueno, Da la clase de Cine y Lite en la perspectiva de Gastronomia, la clase es bastante chiva y los trabajos son super faciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2025-12-20T00:00:00+00:00'::TIMESTAMPTZ, '8ef6ceb59a04bbc1939ce4d37b9f41830e65edad52fca3ac9369c00d59912e9a'::TEXT, ARRAY[681]::BIGINT[]),
    (143::BIGINT, 'Excelente profesor, brinda buena retroalimentación, respeta las horas de trabajo semanales, no califica duro y es muy comprensivo con los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '76d5441ea2025b9b28e075bf06e4960e1fedc912f9679026f8537c5302f13490'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es un profe muy chill, 0 exigente con la materia, lo prepara a uno bien para el futuro, si entrega todos los trabajos y no se la pela en alguan exposición, es casi un 100 asegurado. Si se aprende mucho con él, es muy bueno.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ea992fe1c93592dec7a64d9d094d16e28bb32f54c794aeaef03f07a6e698ba8e'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es muy buen profe, el curso pues es un poco aburrido y no es muy útil, pero se pasa bastante fácil con él, califica bien y las instrucciones son claras, da buena retroalimentación.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '4164525bf7dfce5b3425419c2cfa701afbd880da2d33299851f44ce66225ae61'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Buen profesor para llevar el curso en verano'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2025-02-02T00:00:00+00:00'::TIMESTAMPTZ, '26468de1fe135fd4d36063873ecdfc7178435f75064688b98684e25278c12d91'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'El compa es re-chill y se pasa solo el CFH, por sino lo sabe, el CFH en verano dura solo 1 semana (al menos este sí), entonces con que haga los 4 trabajos de las 4 clases pasa con teja sin pensarlo ni esfuerzo, es re-easy esa vara. Sino entrega un trabajo o falta a clases, pierde el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2025-01-03T00:00:00+00:00'::TIMESTAMPTZ, '3193030dad8a2889ec3dd1491194839d41238daf293b816a908823663f368f93'::TEXT, ARRAY[681]::BIGINT[]),
    (143::BIGINT, 'Matriculé 2 cursos este año, recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2024-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'fd41dd95c57570d94fb3a784a62e7e16987cefbae837772b471d71a4961b60b0'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Excelente profe, matriculé Comu Oral con él porque me gustó mucho Comu Escrita.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-08-09T00:00:00+00:00'::TIMESTAMPTZ, '0efe6183e8c1b06c7dc49cadeca6573bb670f49f2eb672c8f6b9a75d47457167'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Es un buen profe, pero tampoco diría que excelente. Prepárese para las clases más aburridas y poco dinámicas de su vida. Su clase la definiría como fácil, pero aburridísima. Siga las instrucciones y gana ese curso. Un buen punto, brinda apoyo y retroalimentación valiosa.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2024-06-26T00:00:00+00:00'::TIMESTAMPTZ, '83d51c1ba2db97d941a4e6c0a8bc356d424b30e2defda0d4a55c4be1209760c0'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El profe es super buena nota y las evaluaciones son sumamente suaves, no pone mucho trabajo para ser sincero, por ende, se pasa fácil y se entiende todo. Perfecto para entender y pasar rápido el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'c3a6dcc4f15a77377f82e720954cf35161a049f84745d4e02a7cff525a3963bf'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Excelente profe, siempre es muy claro en lo que quiere. Organiza muy bien los trabajos que se tienen que presentar. Comprende muy bien a los estudiantes. Cuando hay trabajos en gropo, él no tiene problema en quitar a los estudiantes que no trabajan.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f1452e66848c7a5fea27c63043e2460d74ffbb6c4e7028c5db3653b0cf125911'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Buen profe, tranquilo y todo muy claro'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'cd0c6d179f60cc826881964815f6190b5bb536282656fecc6f79f0630bba189f'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Excelente profe, entiende demasiado al estudiante, en los trabajos en grupo, no tiene problema con sacar al que no trabaja, además pide una clasificación individual de cada miembro del equipo al final del curso, y da un pequeño porcentaje extra si se fue buen compañero.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'ee1c50d441c1f650034a2382242d098b73132b3f2cf7577f2647acfc6a98d6c7'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Es un profesor súper comprensivo con los estudiantes, califica suave pero siempre está dispuesto a dar una buena retroalimentación. "Mientras usted tenga ganas de trabajar, yo voy a tener ganas de calificarlo." Eso sí, deja muchos trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2024-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'fb733f71ec0e5e72e07c314b34f7b78566feed75b99569aa7638ee692ac429b0'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Es un profe tranquilo y cumple con el crédito del curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '94b64dd7665c9ad63efe2906b0693bf7a505e24089f37ec7841bc5d6916a63f6'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Buen profe, siempre disponible para hacerle consultas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-30T00:00:00+00:00'::TIMESTAMPTZ, '61c3ca7885a3a7ee81ae0fee471dd83d013ec4c5eb9928656035c39d05e7a4c6'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Buen profesor porque sus tareas suelen ser claras y simples, pero a veces él no brinda el apoyo o retroalimentación necesarias para entender lo que uno ha realizado incorrectamente.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'a588aed49c0302538eedb15757034067343a5da72ebccf3352102c4682789f31'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Excelente profe. Siempre dispuesto a ayudar y explicar las dudas, el profe hace que el curso no sea muy aburrido y las evaluaciones son bastante sencillas. Recomendado 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '72a3532ec9d9ac80766ace5c0a94898175b27536e009a466a9332615ff839f7e'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Vocación. El profe es muy buena gente, cualquier duda que tenga siempre lo ayuda y explica varias veces en caso de que no entienda las asignaciones. Las asignaciones no son difíciles, deja tiempo en clase para poder hacerlas y hace pre revisiones antes de entregarlas. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '802ec2af3a47b69660664a4efa91dba60728bdf8922a984567ae2ab928417e1c'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El curso se pasa muy fácil haciendos los trabajos a tiempo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '45b3742f62b4d85f87678d7bf7deda8ac1b005832541de6c178a9a6fcd384e3d'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Si va a todas las clases y hace todos los trabajos se pasa sencillo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a479864f976651fa9a5651e08992d66dea90d1c66b5f380c4a86623a54b30b06'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Excelente profe. Revisa los trabajos antes de entregarlos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3728b0e1b4f1e9f18f0ad25eaad2dea3ea05164dc4906495de5fff3b1c1a59d0'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Un profesor bastante bueno, con mucha vocación, bastante flexible para las fechas de entreg y no deja trabajos muy largos (aparte da tiempo de la clase para terminarlos)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '70280d536070f0849c02716b76775532c2a9d346bdafe564edd4a45690755c83'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Muy buen profesor, se interesa mucho porque todo quede claro y que para que futuros trabajos de investigación uno sepa bastante bien lo que tiene que hacer.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '10ed13f11daa3702469251c31caccdc656b5adba5015305dece5d0e534bc2a1a'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Buen profesor y se preocupa por los estudiantes'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd369b79dcd58782884520119ea0e3e92359c8c0858096e502bfc81ad16ee0075'::TEXT, ARRAY[600]::BIGINT[]),
