    (143::BIGINT, 'Excelente profesor, en todos los sentidos. Posee una gran dedicación por lo que hace. Siempre se preocupa por dar pre revisiones a los trabajos. Así que aproveche eso y no tenga miedo a preguntar sin duda le va asegurar una buena nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'd902e9abed93982bbfddc72298c3217c1d529b618d7a42151986abf54d2f788e'::TEXT, ARRAY[554]::BIGINT[]),
