    (143::BIGINT, 'Muy buen profe, comprensivo, a veces es un poco complicado entender lo que quiere por ejemplo con los esquemas de redacción. En realidad es bueno, lo recomiendo, el curso se pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '4d414eb6145e21c9bdcd5dd865a5dbe9062f55d3e1b08b74037b98ce4106ab5d'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Súper buen profe, es MEEEGA comprensivo con la situación de los estudiantes. Explica muy bien, da retroalimentación constante y deja muy claro lo que quiere. Muy buen profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '3d1843f7576c926a4b507f0a8d96bcbf4d7a3b4731d9eaea8c25b03615205599'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Excelente profe, es muy buena gente y ayuda mucho. Sabe dar bien la clase y tiene mucha consideración con los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'b46ae99aff83a6e79f9f58f09e99d920c5cc8cf36dc295df70aa6a8a2d092b76'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Full recomendando llevar este CFH en verano, son 4 días (1 asincrónico) durante los cuales uno se conecta un rato y luego realiza una pequeña actividad que tiene el resto del día para entregar. El profe es buena gente y el CFH entretenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2022-01-26T00:00:00+00:00'::TIMESTAMPTZ, '2e672dba3a9f2392213675b2e6582c630c9cd40e5e947331004f0b84951a7673'::TEXT, ARRAY[681]::BIGINT[]),
    (143::BIGINT, 'Profesor demasiado bueno, las clases son claras y se preocupa mucho por el estudiante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, '3e5fde09a61c9853ad73ac86e338c71f5e45a23be792b99422aab899c91d3b07'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Es demasiado buen profe! Es súper consciente de la cantidad de créditos del curso y se apega a ello firmemente, lo cual hace el curso aún más fácil. Es muy ordenado y tiene mucho conocimiento. Excelente persona y profe, no duden en matricular con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-15T00:00:00+00:00'::TIMESTAMPTZ, '1b0852419384cffffb1f16e3737f04ac6eaf3afd64ec1c3281c57544723f305f'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es el mejor profesor que he tenido en la universidad. Hace la clase interesante y el curso realmente ayuda para sus habilidades blandas. Respeta las horas por crédito que tiene el curso. Matricule con él sin duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-22T00:00:00+00:00'::TIMESTAMPTZ, '4d36e365e165d9370102fb00244685b343752e537c7c9c3d6ee7a5f02f3fcb23'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'El profesor es muy bueno, las actividades, exposiciones y tareas son muy entretenidas. Definitivamente lo recomiendo, es muy comprensivo y amable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '98e30d4f316894d28f3d2d1e57f63da12353a90fca56d1ec44bb7eda69e28840'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es muy buen profesor, sus clases son muy llevaderas y da muy buena retroalimentación. La verdad es que fue de gran provecho este curso!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases excelentes']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'c730a2cb9ebb10b2d6b811103d49d710028f53e73db9a6afe8d335df4155de3d'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Excelente profesor. Da bastante retroalimentación y es fácil de contactar, siempre dispuesto a ayudar con lo que uno necesite.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'c00d4a5a447e9386f555457dd2e2b880018375232c2aade523a576dd4dbc61ad'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es un excelente profe, siempre está dispuesto a ayudar, explica súper claro y hace el curso bastante llevadero. Es de los pocos profes que hace que el curso valga lo que es, da buena retroalimentación. No dude en matricular con él, super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'd8c2c743b92f559d94d539974079b90efb8186eacfc5cefa89ae1c7ff471ec98'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es un excelente profesor. Siempre da retroalimentación, siempre está atento a consultas, califica suave. Si tiene la oportunidad de llevar cualquier materia con él, dele sin miedo, excelente persona y excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas', 'Brinda apoyo']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '9c3dc09d0be8ad3a4dabd8d77f00b62a5f362fc9b04bca113cc5df4ad3fbb8cc'::TEXT, ARRAY[556]::BIGINT[]),
    (143::BIGINT, 'Este men es calidad, es atento a los estudiantes, comprensivo, accesible a consultas. Imposible que deje el curso a menos que no le ponga ánimos. Es muy consiente y deja una clase asincrónica por semana. Si les toca este curso de una métanse con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-17T00:00:00+00:00'::TIMESTAMPTZ, '0cf62bd5decbed87eee8992df83b9701cd8873d06a51633a3a3d045cc12d329d'::TEXT, ARRAY[556]::BIGINT[]),
    (143::BIGINT, 'Es un curso que se lleva bien, el profe es consciente de que uno tiene mas cursos y eso se refleja en lo comprensivas que son sus evaluaciones. No se puede perder el curso a menos de que se deje muy botado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '9b434d9262abbdf706464175a05234d8d6e06ffb074ff820e74f43f740666933'::TEXT, ARRAY[556]::BIGINT[]),
