    (143::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '714df243ee9bb4f1b20478963e0bd277f0442e21cbaf1ce291b086e4edc2ca8b'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El curso con él se pasa súper fácil, uno aprende demasiado y las clases son muy tranquilas. 100% Recomendado!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '91c7e279aadeb6e0f4d34911622ede62d647725eb58c97bc017394adea364547'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Súper buen profesor, al inicio es un poco intenso, pero con buena intención, ayuda a que uno entienda todo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '94cd00978f5c5ad24ac62b3bc7ea4c000c9da6bf7613d601d8d0f747005c306d'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'No dude en matricular con él. Todos los trabajos se avanzan o hacen en las horas de la clase'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '0b28c5d9f626d8b3b0f82881ff37216633d3b9758a6e0e1036eac50292897110'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Es buena gente, no le molesta que le pregunten y es muy practico. se interesa porque haga bien las cosas, no dude en matricular con él'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, '7cc7ffe6587e52d06072a87b1625d4f7b5c88ef5d96407dc4d47d4c94d62592a'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Su forma de dar la clase la vuelve muy metódica por lo que no aburre ir, además de que ayuda demasiado al estudiante. Excelente!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-26T00:00:00+00:00'::TIMESTAMPTZ, '5492f634f6161cb1e812b5a114342a9e8b356c5d83e24d0ee67225f921159245'::TEXT, ARRAY[556]::BIGINT[]),
    (143::BIGINT, 'Buen profesor. Es fácil pasar el curso con él. No hace trabajos muy largos y evalúa suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2019-01-27T00:00:00+00:00'::TIMESTAMPTZ, '4b7278826789da75d6202bf33026ec4c3c70283a80b4d52edf09c41d471038b9'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Exc profe. Cumple con todo y es super buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'c18ef6b9f5078453d01c4c1059d7f6fd5895daa981a856d7cbc114ae7d60baf1'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es un amor de profe. Lleva la clase súper relajado y no deja mucho que hacer. Califica suave y cae muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2018-12-27T00:00:00+00:00'::TIMESTAMPTZ, '3efdb8403e7e5151add4010054da39c071fffcf85e3572cd7fc262d2c80f0c06'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Muy buen profesor. Deja varios trabajos grupales, incluso algunos de improvisación que son muy interesantes. Califica un poco duro las exposiciones, pero ese es el punto del curso. Muy entretenido y comprensivo :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '36508017086819ddc5996e3946a5fb7c1b979f9727d958070db9da0fd2f0315f'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'un profesor que mide demasiado bien la carga del curso. da las clases lo más compactas que se puede y no deja muchas tareas. califica un poco duro. se nota que le gusta lo que hace.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2018-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'd6d21301567fcb52d74732853f609e1139ff7418171527253f27ac78f98173e8'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es muy ordenado y divertido. Sus clases las hace de la manera más bonita posible y se toma muy en serio que el curso solo valga 1 crédito, por lo que casi no deja tareas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'feffebbaeabfe320cc11e1211dfdf0537076091e649c3d13c7ea8c04437abf6e'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Sus clases son excelentes y me ayudaron un poco a mejorar mi presentación. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes']::TEXT[], '2018-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'fd33191aa5703cbd9501e5ba03336514ee4669424b0b26e161fc1f8f34a9d8f3'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2018-11-23T00:00:00+00:00'::TIMESTAMPTZ, '01ec0072dd68d9b2f1f17e75c52045e2b008f7766161c458704f38579d428222'::TEXT, ARRAY[600, 554]::BIGINT[]),
    (143::BIGINT, 'Es excelente, demasiado buena gente, ayuda mucho con los trabajos para ganarse la mejor nota posible, hace el curso muy fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '788ae753fff25aef3aaead74978b7fdab35083fe173ef435703d4f939478b746'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Muy pura vida y brinda muchísima ayuda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '637d9cb220f441470be34949299e44d6e0de933f93e19c9712de63a3c69e816a'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El profe es demasiado pura vida, el le ayuda a hacer los trabajos(casi que los hace). Apesar de que es muy facil el curso, hay que hacer todos los trabajos porque al final de semestre no perdona nada. Y brinda bastante apoyo al estudiante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '20ebf3fb1d0fbd4295ee5b632fd4845d84aeed74d1185dfff4bfa10ca2d6f53d'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El mejor, casi todo se hace en clase y trata que uno se saque la mejor nota posible'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9d19d697d4ede7ef6c905b6164e9828a73a5ffdb98240c4b24acefce7c2119e5'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El mejor profe de comunicación. Deja siempre adelantar los trabajos en la clase, en el LAIMI. Lo mejor de todo es la retroalimentación que se obtiene, se aprende demasiado haciendo poco.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'de29abed803039cb96f69148a3b84be058a4df31c4a78445f8439b24f6b4e6ce'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '66918f1d44aa5cb5409abaf17db9e03ac4dc10aa2d129362aa98b07a5f05a1ef'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Super buen profe, todo se hace en clases, casi no deja nada para la casa. No hace trabajos extensos ni quices y ayuda bastante.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-05-22T00:00:00+00:00'::TIMESTAMPTZ, '7b341052732b095849ed441dee119ce34b0d7d09e31aea8f2c99cdc66eaf3f3f'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Recomiendo llevar este curso en verano.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, '81500cf8644498f42ac18ca5b2d99997fbe6933927fe41343a1794c9243a4012'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es solo de hacer las tareas y proyectos que deja. Le gusta que le pregunten. La mitad de la clase es magistral (un poco aburrida) y la otra parte dejar hacer los trabajos extra clase. Si le pregunta, prácticamente le hace el trabajo. Es fácil de tratar y comprensivo. Da tiempo extra para entregas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'd8ec6bca7a049c50ef070474cca1c2ec12e09b5c4a37a435930a92d86f2293ff'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'El profe da instrucciones con tiempo y todo se sube al Tec digital. Siempre me ha costado escribir, creo que el curso sí ayuda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '6a1edd1ed2de4b6dadbc94f5d3bb280f28c305383db7009565a7cf106708b986'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Buen profe, la clase tranquila y brinda bastante material de apoyo, el curso no es un queque por qué hay que trabajar y dedicarle tiempo pero es bastante suave'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'c83fb90da5499e2fdf45fbf4932d571c1f9e56beda85cddd287fbe527a602768'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Se trabaja bastante pero se aprende montones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-14T00:00:00+00:00'::TIMESTAMPTZ, '0dc3053d2f0dfb7f6b7fac249f4f92e2509f95baa4aab6d098f3751ca2333683'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Excelente profe. Se preocupa porque uno aprenda, todos los trabajos se hacen en la clase para que uno no esté preocupado por hacerlos, califica suave y uno aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '518cc8d64c58eb4a338c7d7cb64f07f40917288fc6536d86e7915726fc217b04'::TEXT, ARRAY[554]::BIGINT[]),
    (143::BIGINT, 'Es un amor de profe, es demasiado bueno, se concentra en las cosas que debe y le ayuda bastante en la expresión oral, si tienes la opción Nelson es el mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'bf827ad9b2d3d53e2efdbb686a7e0deba24083083debb65c895360c7dbf332db'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Es un excelente profesor, quien se mostrado su interés en darles consejos importantes a los estudiantes que le permitieran ser unos buenos expositores. Se lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2017-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'deb6601c52909331df388b2590321d137942f5e874b78e64def046eb1c775049'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'Trata que los intereses de uno sean utiles en el curso y con eso todo se vuelve más facil.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros']::TEXT[], '2017-01-17T00:00:00+00:00'::TIMESTAMPTZ, '8a241f22da7135c93b69a7a033c2e70710cdda0b73859a854cd2fed867f97760'::TEXT, ARRAY[600]::BIGINT[]),
    (143::BIGINT, 'El entiende la cantidad de creditos, te explica, enseña y te da una buena nota, yo no pensaba matricular el curso, lo hice con el y no me arrepiento'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-12T00:00:00+00:00'::TIMESTAMPTZ, '9bb3e68994f9f492b5694c00d7c67e383f92fe5668b821bee13b02b6267f78c8'::TEXT, ARRAY[600]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
